import {geometry,carbon,DEMO,FORMULA,SOURCE,validateRecord,parseRecords,summarize,csvCell} from './quest-core.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const fmt=(n,d=2)=>n===null?'待補':new Intl.NumberFormat('zh-TW',{maximumFractionDigits:d}).format(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='danan-tree-quest-v1';
let plants=[],records=[],storageWarning='',page='',mapSelection=null,reportSource='platform',mapSource='platform',mapSpecies='';
let draft={steps:8,length:1,eye:1.3,mode:'explore',fixedHeight:9.3,level:true,aligned:false,calibrated:false,circumference:120,group:'broadleaf',species:'樟樹',name:'我的校樹',date:new Date().toLocaleDateString('en-CA'),platformId:'',coefficientMode:'none',bcef:'',r:'',cf:'',source:'',editingId:null};
let dragGeometry=null,storedText=null;
try{storedText=localStorage.getItem(KEY);if(storedText)records=parseRecords(storedText);}catch{storageWarning='本機紀錄無法讀取，未覆寫原資料。請先匯出或檢查瀏覽器儲存設定。';}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function ask(message){return new Promise(resolve=>{const d=$('#confirm-dialog');$('#confirm-message').textContent=message;let accepted=false;$('#confirm-accept').onclick=()=>{accepted=true;d.close();};$('#confirm-cancel').onclick=()=>d.close();d.onclose=()=>resolve(accepted);d.showModal();$('#confirm-cancel').focus();});}
function persist(next,replaceUnreadable=false){if(next.length>1000){toast('最多保留 1000 筆，請先匯出並整理紀錄。');return false;}if(storageWarning&&!replaceUnreadable){toast('請先匯出原始備份，再由老師工具匯入或清除無法讀取的紀錄。');return false;}try{localStorage.setItem(KEY,JSON.stringify({version:1,records:next}));records=next;storageWarning='';return true;}catch{toast('儲存失敗：請確認瀏覽器允許本機儲存或匯出備份。');return false;}}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function head(eyebrow,title,description){return `<div class="section-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="muted">${description}</p></div><span class="badge">大南國小・生態探險</span></div>`;}
function trail(active){return `<div class="trail" aria-label="任務流程">${['校正步長','45° 量樹高','量胸圍','碳儲量估算'].map((s,i)=>`<span class="${active===i?'active':''}"><b>${i+1}</b>${s}</span>`).join('')}</div>`;}
function field(label,id,value,step='any',min='0.01',max='100'){return `<label for="${id}">${label}</label><div class="number-stepper"><button type="button" data-step-target="${id}" data-direction="-1" aria-label="減少${label}">−</button><input id="${id}" type="number" value="${esc(value)}" min="${min}" max="${max}" step="${step}" required inputmode="decimal"><button type="button" data-step-target="${id}" data-direction="1" aria-label="增加${label}">＋</button></div>`;}
function robot(x=0,y=0,scale=1){return `<g transform="translate(${x} ${y}) scale(${scale})"><g class="robot"><path d="M60 28V10" stroke="#1766bf" stroke-width="7"/><path d="M60 15Q62-4 84 0Q82 18 60 15" fill="#44b49a"/><rect x="12" y="25" width="96" height="80" rx="26" fill="#2189dc" stroke="#165994" stroke-width="3"/><rect x="24" y="37" width="72" height="52" rx="15" fill="#f4fcff"/><path d="M38 57l12-7v14zM82 57l-12-7v14z" fill="#1766bf"/><path d="M49 76q11 9 22 0" fill="none" stroke="#1766bf" stroke-width="3" stroke-linecap="round"/><rect x="31" y="107" width="58" height="57" rx="17" fill="#fafefe" stroke="#1766bf" stroke-width="3"/><path d="M60 119l16 9v18l-16 9-16-9v-18z" fill="#70d9cc"/><path d="M50 147l18-19" stroke="#267455" stroke-width="3"/><path d="M28 119L9 137M92 119l20-15" stroke="#1766bf" stroke-width="12" stroke-linecap="round"/><path d="M45 165v19M77 165v19" stroke="#1766bf" stroke-width="13"/><rect x="29" y="180" width="27" height="11" rx="5" fill="#17324a"/><rect x="67" y="180" width="27" height="11" rx="5" fill="#17324a"/></g></g>`;}
function tree(x,y,scale=1){return `<g transform="translate(${x} ${y}) scale(${scale})"><path d="M-9 0l3-134h13L13 0" fill="#b77c47"/><path d="M0-69l-32-36M3-90l29-32" stroke="#996434" stroke-width="7"/><g fill="#64b685" stroke="#458f69" stroke-width="2"><circle cy="-157" r="40"/><circle cx="-35" cy="-128" r="36"/><circle cx="33" cy="-124" r="40"/><circle cy="-112" r="40"/></g><g fill="#91cea0"><circle cx="-15" cy="-170" r="19"/><circle cx="34" cy="-134" r="17"/></g></g>`;}
function home(){
 $('#main').innerHTML=`<section class="hero"><div><span class="badge">給每一位校園小小觀察家</span><h1>用自己的腳步，<br>探索校樹的<em>碳寶藏。</em></h1><p>從一個 45° 的視線開始，量樹高、測胸圍，把校園裡的綠色朋友變成看得懂的科學數據。</p><div class="row"><a class="button primary" href="#height">開始量樹高 <span>→</span></a><a class="button" href="#carbon">進入碳匯實驗室</a></div><p class="hint">四個任務 · 自己動手測量 · 不需要帳號</p></div><div class="hero-art"><svg viewBox="0 0 600 480" role="img" aria-label="原創機器人藍芽芽，在校園探索45度三角形"><defs><pattern id="hero-grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#c9dfef" stroke-width=".6"/></pattern></defs><rect width="600" height="480" fill="url(#hero-grid)"/><circle cx="490" cy="72" r="37" fill="#fff3bc"/><path d="M0 343Q150 275 310 337T600 319V480H0" fill="#c6e6d3"/><g opacity=".7"><rect x="95" y="250" width="270" height="103" rx="7" fill="#f4fcff"/><path d="M80 251l150-48 152 48" fill="#86b8d9"/>${[117,169,221,273,325].map(x=>`<path d="M${x} 270v53" stroke="#89b5d2" stroke-width="23"/>`).join('')}</g>${tree(455,352,1.6)}<path d="M190 302H455V37Z" fill="#fff" fill-opacity=".18" stroke="#2176d2" stroke-width="3" stroke-dasharray="8 6"/><path d="M427 302v-28h28" fill="none" stroke="#2176d2" stroke-width="2"/><path d="M227 302a37 37 0 0 0-11-26" fill="none" stroke="#2176d2" stroke-width="2"/><text x="234" y="285" fill="#1766bf" font-size="20" font-weight="700">45°</text><text x="310" y="329" fill="#1766bf" font-size="16">D</text><text x="470" y="203" fill="#1766bf" font-size="16">D</text>${robot(58,211,.93)}</svg><div class="art-label">兩股一樣長，就能找到樹高。<br><strong>H = D + 眼高</strong></div></div></section><section class="missions" aria-label="探險任務">${[['height','01','△','測量樹高','校正大步，找到 45° 視線'],['carbon','02','◯','測量胸圍','從圓周長認識胸徑'],['carbon','03','↟','計算碳儲存量','看公式如何變成數據'],['map','04','⌖','校園樹木地圖','尋找 127 位綠色朋友']].map(([href,n,icon,title,desc])=>`<a class="mission" href="#${href}"><small>任務 ${n}</small><span class="arrow">↗</span><span class="icon">${icon}</span><strong>${title}</strong><small>${desc}</small></a>`).join('')}</section><div class="note">藍芽芽提醒：1 大步 = 1 公尺只是示範，記得先校正自己的步長。二氧化碳儲存量也不等於每年吸碳量喔！</div><div class="row"><span class="hint">我的本機調查紀錄：${records.length} 筆</span><a href="#reports">查看統計報表 →</a></div>`;
}
function heightPage(){
 $('#main').innerHTML=head('MISSION 01 / GEOMETRY','用 45°，量出一棵樹的高度','先校正腳步，再從兩股等長的三角形找到樹高。')+trail(1)+`<div class="workbench"><div><div class="scene" id="height-scene"><div id="geometry-picture"></div><div class="scene-note" id="geometry-note"></div></div><div class="row tools"><button id="back-step">− 後退一大步</button><button id="forward-step">＋ 前進一大步</button><button id="replay">重播圖解</button><button id="reset-height">重置範例</button></div><details open><summary>一般公式與 45° 等腰直角三角形特例對照</summary><div class="formula">一般公式：H = D × tan(θ) + E<br>45° 特例：tan(45°) = 1，所以 H = D + E<br>水平距離：D = N × L</div><p>直角點 A 在「樹幹與眼高水平線交會處」，眼點 O 到樹梢 T 是斜邊；當 ∠O = 45°，OA = AT = D。樹高還要加上眼高 E。</p><p>相同高度的樹，移動站位會改變仰角。探究模式的樹高則代表不同的假想情境，不是同一棵樹突然長高。</p></details></div><section class="panel"><h2>輸入測量數值</h2><label>測量模式<select id="mode"><option value="explore">探究：固定 45°，比較假想樹高</option><option value="field">實測：固定參考樹高，移動站位</option></select></label><details><summary>① 校正我的大步</summary><div class="pair">${field('測試距離（m）','cal-distance',10,'any','0.1','100')}${field('走了幾大步','cal-steps',10,'any','0.1','100')}</div><button id="calibrate">套用我的平均步長</button></details>${field('每一大步長度（m/步）','length',draft.length,'0.01','0.01','3')}<p class="hint" id="calibration-note"></p>${field('走了幾大步 N','steps',draft.steps,'0.1','0.1','100')}<input id="steps-slider" type="range" min="1" max="30" step="0.1" value="${draft.steps}" aria-label="調整步數">${field('眼睛離地高度 E（m）','eye',draft.eye,'0.01','0.01','3')}<div id="fixed-field">${field('參考樹高（m；用來探究站位）','fixedHeight',draft.fixedHeight,'0.1','0.1','100')}<label class="check"><input id="aligned" type="checkbox" ${draft.aligned?'checked':''}>已用觀測器確認對準 45° 樹梢</label></div><label class="check"><input id="level" type="checkbox" ${draft.level?'checked':''}>觀測點與樹根近似等高，水平距離可用</label><div class="result" aria-live="polite"><span id="height-label">樹高估算</span><strong id="height-value"></strong><p id="height-formula"></p></div><p class="error" id="height-error" role="alert"></p><a class="button primary" id="next-carbon" href="#carbon">下一步：測量胸圍 →</a></section></div>`;
 $('#mode').value=draft.mode;
 for(const key of ['length','steps','eye','fixedHeight'])$('#'+key).oninput=()=>{draft[key]=Number($('#'+key).value);draft.aligned=false;if(key==='length')draft.calibrated=false;drawGeometry();};
 $('#mode').onchange=()=>{draft.mode=$('#mode').value;draft.aligned=false;drawGeometry();};
 $('#steps-slider').oninput=()=>{draft.steps=Number($('#steps-slider').value);$('#steps').value=draft.steps;draft.aligned=false;drawGeometry();};
 $('#level').onchange=()=>{draft.level=$('#level').checked;drawGeometry();};$('#aligned').onchange=()=>{draft.aligned=$('#aligned').checked;drawGeometry();};
 $('#calibrate').onclick=()=>{const d=Number($('#cal-distance').value),n=Number($('#cal-steps').value);if(!(d>0&&d<=100&&n>0&&n<=100&&d/n<=3)){toast('請輸入有效的距離與步數，步長需大於 0 且不超過 3 m。');return;}draft.length=d/n;draft.calibrated=true;$('#length').value=draft.length;draft.aligned=false;drawGeometry();toast('已套用你的校正步長。');};
 $('#back-step').onclick=()=>moveStep(-1);$('#forward-step').onclick=()=>moveStep(1);
 $('#reset-height').onclick=()=>{Object.assign(draft,{steps:8,length:1,eye:1.3,fixedHeight:9.3,mode:'explore',aligned:false,level:true,calibrated:false});heightPage();};
 $('#replay').onclick=()=>{$('#height-scene').classList.remove('replay');requestAnimationFrame(()=>$('#height-scene').classList.add('replay'));};
 $('#next-carbon').onclick=e=>{try{const g=geometry(draft);if(!g.valid)throw Error('請先確認等高地面、45° 與對準條件。');}catch(err){e.preventDefault();$('#height-error').textContent=err.message;}};
 drawGeometry();
}
function moveStep(delta){draft.steps=Math.min(100,Math.max(.1,Math.round((draft.steps+delta)*10)/10));draft.aligned=false;$('#steps').value=draft.steps;drawGeometry();}
function drawGeometry(){
 $('#fixed-field').hidden=draft.mode!=='field';$('#aligned').checked=draft.aligned;$('#steps-slider').value=draft.steps;
 $('#calibration-note').textContent=draft.calibrated?'已校正個人步長。':'尚未校正：目前步長僅供教學探索。';
 try{
 const g=geometry(draft);const scale=Math.min(430/g.distance,310/g.height),ground=385,tx=570,ox=tx-g.distance*scale,ey=ground-draft.eye*scale,ty=ground-g.height*scale,treeScale=(g.height*scale)/197;
 $('#geometry-picture').innerHTML=`<svg id="geo-svg" viewBox="0 0 720 450" role="group" aria-label="水平距離 ${fmt(g.distance)} 公尺，參考樹高 ${fmt(g.height)} 公尺，仰角 ${fmt(g.angle)} 度"><defs><pattern id="geo-grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#cfe4f1" stroke-width=".6"/></pattern></defs><rect width="720" height="450" fill="url(#geo-grid)"/><path d="M0 385H720V450H0" fill="#d2e9d7"/><g opacity=".45"><rect x="45" y="270" width="360" height="90" rx="4" fill="#fff"/>${[65,115,165,215,265,315,365].map(x=>`<rect x="${x}" y="285" width="24" height="46" fill="#91bfd6"/>`).join('')}</g>${tree(tx,ground,treeScale)}<g class="triangle"><path d="M${ox} ${ey}H${tx}V${ty}Z" fill="#2176d2" fill-opacity=".1" stroke="#1766bf" stroke-width="2"/><path d="M${ox} ${ey}L${tx} ${ty}" class="angle-line" stroke="#1766bf" stroke-width="3"/><path d="M${tx-17} ${ey}v-17h17" fill="none" stroke="#1766bf" stroke-width="2"/><path d="M${(ox+tx)/2} ${ey-6}v12M${tx-6} ${(ey+ty)/2}h12" stroke="#1766bf" stroke-width="2"/><path d="M${ox+38} ${ey}A38 38 0 0 0 ${ox+38*Math.cos(g.angle*Math.PI/180)} ${ey-38*Math.sin(g.angle*Math.PI/180)}" stroke="#1766bf" stroke-width="2" fill="none"/><text x="${ox+45}" y="${ey-12}" fill="#1766bf" font-size="19" font-weight="700">${fmt(g.angle,1)}°</text></g><path d="M${ox} ${ground}V${ey}" stroke="#e19a49" stroke-width="4"/><g aria-hidden="true"><circle cx="${ox-10}" cy="${ey+2}" r="13" fill="#f3c58e" stroke="#815c3d" stroke-width="1.5"/><path d="M${ox-23} ${ey}q0-24 23-10l-4 9" fill="#594838"/><path d="M${ox-17} ${ey+16}l-6 ${Math.max(8,(ground-ey)*.4)}h25l-4 -${Math.max(8,(ground-ey)*.4)}" fill="#68ace0"/><path d="M${ox-15} ${ground-12}v12m13-12v12" stroke="#314e70" stroke-width="5"/><path d="M${ox-2} ${ey+21}l10-12" stroke="#e6b27c" stroke-width="5"/></g><circle cx="${ox}" cy="${ey}" r="4" fill="#fff" stroke="#1766bf" stroke-width="2"/><circle cx="${tx}" cy="${ty}" r="5" fill="#1766bf"/><text x="${ox-17}" y="${ey-18}" fill="#17324a" font-size="14">O 眼點</text><text x="${tx+12}" y="${ey-6}" fill="#17324a" font-size="14">A 直角點</text><text x="${tx+12}" y="${Math.max(26,ty-8)}" fill="#17324a" font-size="14">T 樹梢</text><text x="${(ox+tx)/2}" y="${Math.min(ground-14,ey+25)}" text-anchor="middle" fill="#1766bf" font-size="16">D = ${fmt(g.distance)} m</text><text x="${tx+22}" y="${(ey+ty)/2}" fill="#1766bf" font-size="15">${fmt(g.height-draft.eye)} m</text><text x="${Math.max(8,ox-70)}" y="${ground+27}" fill="#17324a" font-size="14">E = ${fmt(draft.eye)} m</text><text x="${tx+12}" y="${ground+29}" fill="#1766bf" font-size="19" font-weight="700">H = ${fmt(g.height)} m</text><g id="observer-handle" role="slider" tabindex="0" aria-label="拖曳眼點調整觀測距離，也可用左右方向鍵" aria-valuenow="${draft.steps}" aria-valuemin="0.1" aria-valuemax="100" class="draggable"><circle cx="${ox}" cy="${ey}" r="22" fill="transparent"/></g></svg>`;
 $('#height-value').textContent=g.valid?fmt(g.estimatedHeight)+' m':'條件未成立';
 $('#height-label').textContent=draft.mode==='explore'?'假想樹高（教學示範）':'樹高估算（確認觀測後採用）';
 $('#height-formula').textContent=`D = ${fmt(draft.steps)} × ${fmt(draft.length)} = ${fmt(g.distance)} m；${draft.mode==='explore'?'H = '+fmt(g.distance)+' + '+fmt(draft.eye)+' = '+fmt(g.height)+' m':'θ = arctan((H − E) ÷ D) = '+fmt(g.angle,1)+'°；對準後 H = D + E = '+fmt(g.distance+draft.eye)+' m'}`;
 $('#geometry-note').textContent=draft.mode==='explore'?'探究模式：固定 45°，拖曳眼點或調整步數，比較不同假想樹高。':'實測模式：參考樹高固定；移動站位會改變角度，接近 45°（±0.5°）並確認觀測後才可採用。';
 $('#height-error').textContent=g.valid?'':!draft.level?'地面條件不適用，請重新選擇平坦測量點。':!draft.calibrated&&draft.mode==='field'?'實測前，請先展開「校正我的大步」並套用測量值。':'請移動站位至接近 45°，再勾選已對準樹梢。';
 const handle=$('#observer-handle'),picture=$('#geometry-picture');
 handle.onpointerdown=e=>{e.preventDefault();dragGeometry={scale,tx};picture.setPointerCapture(e.pointerId);};
 picture.onpointermove=e=>{if(!dragGeometry)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform($('#geo-svg').getScreenCTM().inverse());const n=(dragGeometry.tx-p.x)/dragGeometry.scale/draft.length;draft.steps=Math.min(100,Math.max(.1,Math.round(n*10)/10));draft.aligned=false;$('#steps').value=draft.steps;drawGeometry();};
 picture.onpointerup=()=>{dragGeometry=null;};picture.onpointercancel=()=>{dragGeometry=null;};handle.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();moveStep(e.key==='ArrowLeft'?1:-1);$('#observer-handle').focus();}};
 }catch(err){$('#height-value').textContent='請檢查輸入';$('#height-error').textContent=err.message;}
}
function coefficients(){
 if(draft.coefficientMode==='none')return null;
 return {bcef:Number(draft.bcef),r:draft.r===''?NaN:Number(draft.r),cf:Number(draft.cf),mode:draft.coefficientMode,source:draft.source.trim()};
}
function carbonPage(){
 const species=[...new Set(plants.map(p=>p.species))].sort((a,b)=>a.localeCompare(b,'zh-TW'));
 $('#main').innerHTML=head('MISSION 02–04 / CARBON LAB','測胸圍，打開校樹的碳寶藏','先選擇樹木與測量日期，再把胸圍換成胸徑、材積與碳儲量。')+trail(2)+`<div class="workbench"><div><div class="carbon-scene"><svg viewBox="0 0 600 280" role="img" aria-label="在離地約1.3公尺測胸圍；圓周長等於直徑乘以圓周率"><path d="M100 265H500" stroke="#7cb59b" stroke-width="3"/><path d="M210 260l12-230h150l20 230" fill="#ba8858"/><path d="M243 32l-5 210M276 32l4 211M345 33l14 209" stroke="#a16c3d" stroke-width="4"/><ellipse cx="300" cy="139" rx="100" ry="25" fill="#fff1bc" stroke="#bd8225" stroke-width="3"/><path d="M200 139q100 45 200 0" fill="none" stroke="#e6a643" stroke-width="15"/><path d="M235 155v10m25-6v10m25-6v10m25-6v10m25-9v10m25-13v10" stroke="#825616" stroke-width="2"/><text x="300" y="120" text-anchor="middle" font-size="18" fill="#17324a">胸圍 C</text><path d="M160 260V139h25" stroke="#1766bf" fill="none" stroke-width="2"/><text x="65" y="200" font-size="17" fill="#1766bf">約 1.3 m</text><circle cx="478" cy="97" r="48" fill="#e1c09a" stroke="#8a5e36" stroke-width="3"/><path d="M430 97h96" stroke="#1766bf" stroke-width="3"/><text x="478" y="171" text-anchor="middle" font-size="16" fill="#1766bf">DBH = C ÷ π</text>${robot(24,15,.56)}</svg></div><div class="stats" aria-live="polite"><div class="stat"><span>樹高 H</span><strong id="lab-height">—</strong></div><div class="stat"><span>胸徑 DBH</span><strong id="dbh-value">—</strong></div><div class="stat"><span>材積 V</span><strong id="volume-value">—</strong></div></div><section class="panel"><span class="badge orange" id="result-badge">教學估算</span><h2 style="margin-top:15px">二氧化碳儲存量估算</h2><div class="result"><strong id="co2-value">待補係數</strong><p id="co2-note"></p></div><details open><summary>保留原始公式・看看數字怎麼來</summary><div class="formula">DBH<sub>cm</sub> = C<sub>cm</sub> ÷ π<br>DBH<sub>m</sub> = DBH<sub>cm</sub> ÷ 100<br>V = DBH<sub>m</sub>² × 0.79 × H × F<br>T<sub>CO₂,t</sub> = V × BCEF × (1 + R) × CF × 44/12<br>T<sub>CO₂,kg</sub> = T<sub>CO₂,t</sub> × 1000</div><p id="substitution" class="hint"></p><p class="hint">F：闊葉 0.45／針葉 0.50；0.79 是 π/4 的近似值。BCEF 使用 t 生物量/m³；R 為地下／地上生物量比，CF 為含碳比例，44/12 為 C 到 CO₂ 質量換算。</p><a href="${SOURCE}" target="_blank" rel="noopener">查看官方公式與定義 ↗</a></details></section><div class="note">這是指定方法的儲存量估算，不是年吸碳或碳排放量。樹幹非正圓、步幅和觀測角度都會帶來誤差；板根、分叉、棕櫚等請教師確認。</div></div><form class="panel" id="lab-form"><h2>我的校樹調查</h2><label>校樹對照（選填）<select id="platform-tree"><option value="">自行調查／尚未對照</option>${plants.map(p=>`<option value="${p.id}">${esc(p.label+'｜'+p.species)}</option>`).join('')}</select></label><label>樹木名稱<input id="tree-name" maxlength="100" value="${esc(draft.name)}" required></label><label>樹種<input id="species" list="species-list" value="${esc(draft.species)}" maxlength="100" required><datalist id="species-list">${species.map(s=>`<option value="${esc(s)}">`).join('')}</datalist></label><label>樹形分類（請教師確認）<select id="group"><option value="broadleaf">闊葉樹・F = 0.45</option><option value="conifer">針葉樹・F = 0.50</option><option value="other">其他／未確認・不套用公式</option></select></label><label>測量日期<input type="date" id="date" value="${esc(draft.date)}" required></label>${field('離地約 1.3 m 的胸圍 C（cm）','circumference',draft.circumference,'0.1','0.1','3000')}<input id="circumference-slider" type="range" min="10" max="400" step="1" value="${draft.circumference}" aria-label="調整胸圍"><p class="hint">樹高由前一步帶入。<a href="#height">返回樹高測量</a></p><details open><summary>碳儲量係數與來源</summary><label>係數模式<select id="coefficientMode"><option value="none">尚缺適用係數：只計算材積</option><option value="demo">教師示範假設值</option><option value="sourced">教師輸入有依據的係數</option></select></label><div id="coefficient-fields"><div class="pair">${field('BCEF（t/m³）','bcef',draft.bcef,'any','0.001','10')}${field('根莖比 R','r',draft.r,'any','0','10')}</div>${field('含碳率 CF（0–1）','cf',draft.cf,'any','0.001','1')}<label>來源、適用樹種與範圍<textarea id="coefficient-source" maxlength="1500" rows="3" placeholder="請記錄文獻／網址、樹種及係數適用範圍">${esc(draft.source)}</textarea></label><p class="hint" id="coefficient-hint"></p></div></details><p id="lab-error" class="error" role="alert"></p><button class="primary" type="submit" id="save-tree">${draft.editingId?'更新這筆紀錄':'儲存到我的校樹'} ＋</button><p class="hint">探究模式或示範係數的紀錄皆標為「示範」，不混入實測統計。</p></form></div>`;
 for(const k of ['group','coefficientMode'])$('#'+k).value=draft[k];$('#platform-tree').value=draft.platformId;
 for(const [id,key] of [['tree-name','name'],['species','species'],['date','date'],['group','group'],['coefficientMode','coefficientMode'],['circumference','circumference'],['bcef','bcef'],['r','r'],['cf','cf'],['coefficient-source','source']]){
  $('#'+id).addEventListener(id==='group'||id==='coefficientMode'?'change':'input',()=>{draft[key]=key==='circumference'?Number($('#'+id).value):$('#'+id).value;drawCarbon();});
 }
 $('#platform-tree').onchange=()=>{draft.platformId=$('#platform-tree').value;const p=plants.find(p=>p.id===draft.platformId);if(p){draft.name=p.label+' 的調查';draft.species=p.species;draft.group='other';$('#group').value='other';$('#tree-name').value=draft.name;$('#species').value=draft.species;}drawCarbon();};
 $('#circumference-slider').oninput=()=>{draft.circumference=Number($('#circumference-slider').value);$('#circumference').value=draft.circumference;drawCarbon();};
 $('#lab-form').onsubmit=e=>{e.preventDefault();saveTree();};drawCarbon();
}
function drawCarbon(){
 $('#coefficient-fields').hidden=draft.coefficientMode==='none';
 for(const el of $$('#coefficient-fields input, #coefficient-fields textarea'))el.required=draft.coefficientMode!=='none';
 $('#circumference-slider').value=draft.circumference;
 $('#coefficient-hint').textContent=draft.coefficientMode==='demo'?'示範假設值／非官方樹種實測值。老師工具可載入示範。':'教師需確認引用係數適用本樹種，BCEF 已含密度，不重複相乘。';
 try{const g=geometry(draft);if(!g.valid)throw Error('樹高量測條件不成立，請返回前一步確認 45° 與等高條件。');const c=carbon({circumference:draft.circumference,height:g.estimatedHeight,group:draft.group,coefficients:coefficients()});
 $('#lab-height').innerHTML=fmt(g.estimatedHeight)+' <small>m</small>';$('#dbh-value').innerHTML=fmt(c.dbhCm)+' <small>cm</small>';$('#volume-value').innerHTML=fmt(c.volume,4)+' <small>m³</small>';
 $('#co2-value').textContent=c.co2Kg===null?'待補充樹種係數':fmt(c.co2Kg)+' kg CO₂';
 $('#result-badge').textContent=draft.mode==='explore'||draft.coefficientMode==='demo'?'教學示範・不列入實測統計':'本機調查・估算結果';
 $('#co2-note').textContent=c.co2Kg===null?'目前僅完成胸徑與材積；缺值不視為零。':draft.coefficientMode==='demo'?'使用示範假設係數，結果不是官方樹種估值。':'使用教師提供係數，適用性需由教師確認。';
 $('#substitution').textContent=`DBH = ${fmt(draft.circumference)} ÷ π = ${fmt(c.dbhCm)} cm = ${fmt(c.dbhM,4)} m；V = ${fmt(c.dbhM,4)}² × 0.79 × ${fmt(g.estimatedHeight)} × ${c.f} = ${fmt(c.volume,4)} m³。`+(c.co2Kg===null?'':` CO₂ = ${fmt(c.volume,4)} × ${draft.bcef} × (1 + ${draft.r}) × ${draft.cf} × 44/12 × 1000 = ${fmt(c.co2Kg)} kg。中間運算保留完整精度。`);
 $('#lab-error').textContent='';$('#save-tree').disabled=false;
 }catch(err){$('#co2-value').textContent='請檢查資料';$('#lab-error').textContent=err.message;$('#save-tree').disabled=true;for(const id of ['lab-height','dbh-value','volume-value'])$('#'+id).textContent='—';$('#substitution').textContent='';}
}
function saveTree(){
 try{
 const g=geometry(draft),p=plants.find(p=>p.id===draft.platformId);
 const r=validateRecord({id:draft.editingId||crypto.randomUUID(),name:draft.name.trim(),species:draft.species.trim(),date:draft.date,circumference:draft.circumference,height:g.estimatedHeight,group:draft.group,coefficients:coefficients(),formulaId:FORMULA,sourceUrl:SOURCE,estimatedAt:new Date().toISOString(),measurementMethod:g.measurementMethod,measurement:{steps:draft.steps,length:draft.length,eye:draft.eye,fixedHeight:draft.fixedHeight,level:draft.level,aligned:draft.aligned,calibrated:draft.calibrated},demo:draft.mode==='explore'||draft.coefficientMode==='demo',platformId:p?.id||null,location:p?{x:p.x,z:p.z}:null});
 const next=records.filter(a=>a.id!==r.id);next.push(r);if(next.length>1000)throw Error('最多保留 1000 筆，請先匯出並整理。');if(!persist(next))return;draft.editingId=null;toast('已儲存本機紀錄，示範與實測會分開統計。');location.hash='reports';
 }catch(err){$('#lab-error').textContent=err.message;}
}
function currentRows(source){
 if(source==='platform')return plants.map(p=>({...p,name:p.label+'｜'+p.species,co2Kg:p.sourceStockCO2e,location:{x:p.x,z:p.z},platform:true}));
 // Use the latest observation per physical tree to avoid counting repeat surveys as new trees.
 const latest=new Map();for(const r of records.filter(r=>source==='demo'?r.demo:!r.demo)){const key=r.platformId||r.id;const old=latest.get(key);if(!old||r.date>old.date||(r.date===old.date&&r.estimatedAt>old.estimatedAt))latest.set(key,r);}
 return [...latest.values()].map(r=>({...r,co2Kg:r.result.co2Kg}));
}
function sourceOptions(value){return `<option value="platform" ${value==='platform'?'selected':''}>教育部平台校樹資料</option><option value="field" ${value==='field'?'selected':''}>我的實測紀錄（最新一次）</option><option value="demo" ${value==='demo'?'selected':''}>我的示範紀錄（獨立統計）</option>`;}
function color(v){return v===null?'#8497a3':v>=500?'#1766bf':v>=200?'#229b73':'#d48029';}
function mapPage(){
 const rows=currentRows(mapSource),list=mapSpecies?rows.filter(r=>r.species===mapSpecies):rows;
 const species=[...new Set(rows.map(r=>r.species))].sort((a,b)=>a.localeCompare(b,'zh-TW'));
 $('#main').innerHTML=head('CAMPUS / TREE ATLAS','校園樹木地圖','點選樹木查看數據；位置沿用平台座標近似對齊，校舍用途與現況待確認。')+`<div class="tools"><label>資料集<select id="map-source">${sourceOptions(mapSource)}</select></label><label>篩選樹種<select id="map-species"><option value="">所有樹種（${rows.length} 株）</option>${species.map(s=>`<option ${s===mapSpecies?'selected':''}>${esc(s)}</option>`).join('')}</select></label><a class="button" href="#reports">查看統計 →</a></div><div class="map-layout"><div><div class="map-scene"><svg viewBox="0 0 760 620" role="img" aria-label="校園配置與 ${list.filter(r=>r.location).length} 個樹木位置。下方列表提供相同資料。"><defs><pattern id="map-grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#cee3cc" stroke-width=".6"/></pattern></defs><rect width="760" height="620" fill="url(#map-grid)"/><g transform="translate(44,-80) scale(1.65)"><polygon points="36,326 73,286 180,224 248,196 308,214 345,291 391,328 420,469 364,530 193,550 138,516 94,438" fill="#d8e9c5" stroke="#90b185" stroke-width="2"/><path d="M0 335L90 258 186 185 298 87" stroke="#b5c2ca" fill="none" stroke-width="23"/><path d="M0 335L90 258 186 185 298 87" stroke="#fff" fill="none" stroke-dasharray="6 6"/><path d="M110 385L315 270M125 410l55 85 155-90" fill="none" stroke="#eee2c7" stroke-width="22"/><polygon points="105,368 305,254 323,283 122,397" fill="#84aed0" stroke="#fff" stroke-width="2"/><polygon points="111,434 142,416 191,495 157,514" fill="#84aed0" stroke="#fff" stroke-width="2"/><ellipse cx="288" cy="418" rx="100" ry="65" transform="rotate(-29 288 418)" fill="#d78f77" stroke="#fdf8e7" stroke-width="3"/><ellipse cx="288" cy="418" rx="86" ry="50" transform="rotate(-29 288 418)" fill="#94c498" stroke="#fff" stroke-width="2"/><text x="270" y="420" fill="#244d43" font-size="11">操場示意</text><text x="165" y="354" fill="#183a5a" font-size="10" transform="rotate(-29 165 354)">校舍示意</text>${list.filter(r=>r.location).map(r=>{const mpp=78.2/Math.hypot(197,112),x=r.location.x/mpp+84,y=r.location.z/mpp+365;return `<circle class="map-marker" data-tree="${esc(r.id)}" cx="${x}" cy="${y}" r="4.5" fill="${color(r.co2Kg)}" tabindex="0" role="button" aria-label="${esc(r.name)}，${r.co2Kg===null?'儲存量缺值':fmt(r.co2Kg)+' 公斤'}"><title>${esc(r.name)}</title></circle>`;}).join('')}</g></svg><div class="legend"><span style="--color:#1766bf">≥ 500 kg</span><span style="--color:#229b73">200–500 kg</span><span style="--color:#d48029">&lt; 200 kg</span><span style="--color:#8497a3">缺值</span></div></div><p class="hint">${mapSource==='platform'?'平台單位：kg CO₂e；擷取日期 2026-10-28，並非近期現勘。':'本機單位：kg CO₂。沒有對照校樹的紀錄僅列於下表，不虛構地點。'}</p></div><section class="panel" id="map-detail"><h2>選一棵綠色朋友</h2><p class="muted">點選地圖標記或下方列表，查看樹高、胸徑與碳儲量。</p>${robot(30,20,1)}</section></div><div class="table-wrap"><table><caption class="hint">目前篩選 ${list.length} 株（無座標紀錄不顯示標記）</caption><thead><tr><th>校樹</th><th>樹種</th><th class="num">儲存量（${mapSource==='platform'?'kg CO₂e':'kg CO₂'}）</th><th>操作</th></tr></thead><tbody>${list.map(r=>`<tr><td>${esc(r.label||r.name)}</td><td>${esc(r.species)}</td><td class="num">${fmt(r.co2Kg)}</td><td><button data-tree="${esc(r.id)}">查看</button></td></tr>`).join('')}</tbody></table>${!list.length?'<p class="empty">這個資料集尚無紀錄。先到量測頁儲存一棵校樹吧！</p>':''}</div>`;
 $('#map-source').onchange=()=>{mapSource=$('#map-source').value;mapSpecies='';mapSelection=null;mapPage();};$('#map-species').onchange=()=>{mapSpecies=$('#map-species').value;mapSelection=null;mapPage();};
 for(const el of $$('[data-tree]')){const select=()=>showTree(rows.find(r=>r.id===el.dataset.tree));el.onclick=select;if(el.tagName.toLowerCase()==='circle')el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};}
 if(mapSelection){const r=list.find(r=>r.id===mapSelection);if(r)showTree(r);}
}
function showTree(r){
 mapSelection=r.id;$('#map-detail').innerHTML=`<span class="badge ${r.demo?'orange':''}">${r.platform?'教育部平台紀錄':r.demo?'本機示範':'本機實測'}</span><h2 style="margin-top:14px">${esc(r.name)}</h2><p>${esc(r.species)}</p><p>樹高：${fmt(r.height)} m<br>胸徑：${fmt(r.platform?r.dbh:r.result.dbhCm)} cm</p><div class="result"><span>二氧化碳儲存量${r.platform?'（平台估算）':''}</span><strong>${fmt(r.co2Kg)} <small>${r.platform?'kg CO₂e':'kg CO₂'}</small></strong></div><p class="hint">${r.platform?'原始座標 '+fmt(r.latitude,6)+', '+fmt(r.longitude,6)+'；平台估算非年吸碳。':esc(r.date)+' · '+esc(r.coefficients?.source||'缺適用係數')}<br>配置示意，現場位置與樹種仍請確認。</p>${r.platform?`<a class="button" href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">查看來源 ↗</a><button id="survey-tree" class="primary" style="margin-top:10px">調查這棵樹 →</button>`:''}`;
 if(r.platform)$('#survey-tree').onclick=()=>{draft.platformId=r.id;draft.name=r.label+' 的調查';draft.species=r.species;draft.group='other';draft.editingId=null;location.hash='carbon';};
}
function countChart(rows){
 const counts=[...rows].sort((a,b)=>b.count-a.count),top=counts.slice(0,5),rest=counts.slice(5).reduce((n,r)=>n+r.count,0);if(rest)top.push({species:'其他樹種',count:rest});
 const total=top.reduce((n,r)=>n+r.count,0),colors=['#1766bf','#20a584','#eba346','#8a68c9','#55abc7','#b2c7d8'];let offset=0;
 const segments=top.map((r,i)=>{const length=r.count/total*251.327,svg=`<circle cx="100" cy="100" r="40" fill="none" stroke="${colors[i]}" stroke-width="22" stroke-dasharray="${length} 251.327" stroke-dashoffset="${-offset}" transform="rotate(-90 100 100)"/>`;offset+=length;return svg;}).join('');
 return total?`<svg viewBox="0 0 200 200" role="img" aria-label="樹種株數比例，下方列出相同數據">${segments}<text x="100" y="102" text-anchor="middle" fill="#17324a" font-size="20" font-weight="700">${total}</text><text x="100" y="121" text-anchor="middle" fill="#506b80" font-size="11">株校樹</text></svg><ul class="pie-legend">${top.map((r,i)=>`<li><span style="--color:${colors[i]}">${esc(r.species)}</span><strong>${fmt(r.count/total*100,1)}% · ${r.count} 株</strong></li>`).join('')}</ul>`:'<p class="empty">尚無紀錄</p>';
}
function reportsPage(){
 const rows=currentRows(reportSource),s=summarize(rows),unit=reportSource==='platform'?'kg CO₂e':'kg CO₂',max=Math.max(...s.bySpecies.map(r=>r.total),1);
 $('#main').innerHTML=head('REPORT / OUR GREEN CAMPUS','每一份觀察，都讓校園更清楚','分開查看平台、實測和示範，不把不同方法或單位的儲量相加。')+`<div class="tools"><label>統計資料集<select id="report-source">${sourceOptions(reportSource)}</select></label><button id="report-csv">匯出目前統計 CSV ↓</button><a class="button" href="#map">查看校樹地圖 →</a></div><div class="stats"><div class="stat"><span>調查樹木</span><strong>${s.count} <small>株</small></strong></div><div class="stat"><span>${s.missing?'已知值小計（非完整總量）':'碳儲存量合計'}</span><strong>${s.count?fmt(s.total):'—'} <small>${unit}</small></strong></div><div class="stat"><span>樹種 / 儲量缺值</span><strong>${s.bySpecies.length} <small>種 / ${s.missing} 株待補</small></strong></div></div><div class="note">${reportSource==='platform'?'平台資料：127 株中 124 株有估算值、3 株缺值。小計不是全校完整盤查，不是年度吸碳。':reportSource==='demo'?'這裡僅統計教學示範，結果不能當作真實校樹碳匯。':'本機實測只包含你儲存的紀錄；同一平台樹以最新一次調查計入，避免重複加總。'} 年吸碳需同樹、不同日期且可比的重測；本版不以單次儲存量推算。</div><div class="report-panels"><section class="panel"><h2>各樹種碳儲存量</h2><p class="hint">單位 ${unit} · 前 8 種已知值小計，其餘見下表；* 表示有缺值</p><div class="bars">${s.bySpecies.slice(0,8).map(r=>`<div class="bar"><span>${esc(r.species)}</span><div class="bar-track"><div class="bar-fill" style="width:${r.total/max*100}%"></div></div><span>${fmt(r.total)}${r.missing?' *':''}</span></div>`).join('')||'<p class="empty">還沒有紀錄。完成一次測量並儲存後，就會出現統計。</p>'}</div></section><section class="panel"><h2>樹種株數比例</h2><div class="pie-chart">${countChart(s.bySpecies)}</div></section></div><div class="table-wrap"><table><thead><tr><th>樹種</th><th class="num">株數</th><th class="num">已知值小計（${unit}）</th><th class="num">缺值株數</th></tr></thead><tbody>${s.bySpecies.map(r=>`<tr><td>${esc(r.species)}</td><td class="num">${r.count}</td><td class="num">${fmt(r.total)}</td><td class="num">${r.missing}</td></tr>`).join('')}</tbody></table></div><h2>我的調查紀錄</h2><p class="hint">所有日期的紀錄均保留於下表；統計按資料集分組，同一校樹僅採最新一次。重新整理後仍可讀取。</p><div class="tools"><button id="records-json">匯出全部本機 JSON ↓</button><button id="records-csv">匯出全部本機 CSV ↓</button></div><div class="table-wrap"><table><thead><tr><th>名稱 / 樹種</th><th>日期</th><th>資料類別</th><th class="num">kg CO₂</th><th>操作</th></tr></thead><tbody>${records.map(r=>`<tr><td>${esc(r.name)} / ${esc(r.species)}</td><td>${esc(r.date)}</td><td>${r.demo?'示範':'實測'}</td><td class="num">${fmt(r.result.co2Kg)}</td><td><button data-edit="${r.id}">編輯</button> <button data-copy="${r.id}">複製</button> <button class="danger" data-delete="${r.id}">刪除</button></td></tr>`).join('')}</tbody></table>${records.length?'':'<p class="empty">尚無本機調查紀錄。<a href="#height">開始量樹高 →</a></p>'}</div>`;
 $('#report-source').onchange=()=>{reportSource=$('#report-source').value;reportsPage();};
 $('#report-csv').onclick=()=>download('校樹統計.csv','\ufeff'+[['資料集','樹種','株數','已知值小計', '單位','缺值株數'],...s.bySpecies.map(r=>[reportSource,r.species,r.count,r.total,unit,r.missing])].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');
 $('#records-json').onclick=exportJSON;$('#records-csv').onclick=exportCSV;
 for(const b of $$('[data-edit]'))b.onclick=()=>editRecord(b.dataset.edit);
 for(const b of $$('[data-copy]'))b.onclick=()=>{const r=records.find(r=>r.id===b.dataset.copy);if(persist([...records,{...r,id:crypto.randomUUID(),name:r.name+'（複本）',estimatedAt:new Date().toISOString()}]))reportsPage();};
 for(const b of $$('[data-delete]'))b.onclick=async()=>{if(await ask('刪除這筆本機紀錄？建議先匯出備份。')&&persist(records.filter(r=>r.id!==b.dataset.delete)))reportsPage();};
}
function editRecord(id){const r=records.find(r=>r.id===id);Object.assign(draft,r.measurement,{mode:r.measurementMethod==='field_45_degree'?'field':'explore',editingId:r.id,name:r.name,species:r.species,date:r.date,circumference:r.circumference,group:r.group,platformId:r.platformId||'',coefficientMode:r.coefficients?.mode||'none',bcef:r.coefficients?.bcef??'',r:r.coefficients?.r??'',cf:r.coefficients?.cf??'',source:r.coefficients?.source||''});location.hash='carbon';}
function exportJSON(){download(storageWarning?'校樹原始備份.json':'校樹調查紀錄.json',storageWarning&&storedText?storedText:JSON.stringify({version:1,records},null,2),'application/json');}
function exportCSV(){const table=[['編號','名稱','樹種','日期','類別','樹高_m','胸圍_cm','胸徑_cm','材積_m3','儲量_kgCO2','方法','係數來源'],...records.map(r=>[r.id,r.name,r.species,r.date,r.demo?'示範':'實測',r.height,r.circumference,r.result.dbhCm,r.result.volume,r.result.co2Kg,r.measurementMethod,r.coefficients?.source||''])];download('校樹調查紀錄.csv','\ufeff'+table.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function render(){page=location.hash.slice(1)||'home';if(!['home','height','carbon','map','reports'].includes(page))page='home';for(const a of $$('nav a')){if(a.hash==='#'+page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}({home,height:heightPage,carbon:carbonPage,map:mapPage,reports:reportsPage}[page])();if(storageWarning)toast(storageWarning);}
$('#teacher-open').onclick=()=>{$('#storage-message').textContent=storageWarning||`本機共 ${records.length} 筆紀錄。匯入會取代現有資料，請先匯出。`;$('#teacher').showModal();};$('[data-close]').onclick=()=>$('#teacher').close();
$('#contrast').onclick=()=>document.body.classList.toggle('high-contrast');
$('#demo').onclick=()=>{Object.assign(draft,{coefficientMode:'demo',bcef:DEMO.bcef,r:DEMO.r,cf:DEMO.cf,source:DEMO.source});$('#teacher').close();if(page==='carbon')carbonPage();else location.hash='carbon';toast('已載入示範假設係數，結果會標為教學示範。');};
$('#export-json').onclick=exportJSON;$('#export-csv').onclick=exportCSV;
$('#clear-local').onclick=async()=>{if(await ask('清除所有本機校樹紀錄？此操作無法復原，請先匯出備份。')&&persist([],true)){$('#storage-message').textContent='已清除本機紀錄。';render();}};
$('#import-json').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('JSON 檔案需小於 5 MB。');const next=parseRecords(await file.text());if(!await ask(`匯入 ${next.length} 筆並取代目前的 ${records.length} 筆紀錄？`))return;if(persist(next,true)){$('#storage-message').textContent=`已匯入 ${next.length} 筆。`;render();}}catch(err){$('#storage-message').textContent='匯入失敗：'+err.message;}finally{e.target.value='';}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-step-target]');if(!b)return;const input=document.getElementById(b.dataset.stepTarget);const step=input.step==='any'?0.1:Number(input.step);const old=Number(input.value),next=old+step*Number(b.dataset.direction);if(next<Number(input.min)||next>Number(input.max))return;input.value=Number(next.toFixed(6));input.dispatchEvent(new Event('input',{bubbles:true}));});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
try{const r=await fetch('./plants.json');if(!r.ok)throw Error();plants=await r.json();if(!Array.isArray(plants)||plants.length!==127)throw Error();render();}catch{$('#main').innerHTML='<h1>校樹資料暫時無法載入</h1><p>請重新整理，或檢查 plants.json 是否隨網站一起發布。</p>';}
